import React from 'react';
import { AbsoluteFill, interpolate, useCurrentFrame } from 'remotion';
import { COLORS, EASINGS } from '../../brand';
import { FONT_BODY, FONT_MONO } from '../../fonts';
import { CLAMP } from '../../lib/kit';
import { CaptionTrack, CoverImage, HookTitle, ProgressBar, SAFE, ShortBg, ToolCard, Watermark, secToFrame } from '../../lib/shorts';
import { WORDS } from './words';

// short-126: generated by the daily batch. Cover held at frame 0; closes on the cover.
export const compositionConfig = { id: 'Short126', durationInSeconds: 32.9, fps: 30, width: 1080, height: 1920 };

const FadeOut: React.FC<{ at: number; children: React.ReactNode }> = ({ at, children }) => {
  const frame = useCurrentFrame();
  const op = 1 - interpolate(frame, [at - 8, at + 2], [0, 1], { ...CLAMP, easing: EASINGS.easeIn });
  return <AbsoluteFill style={{ opacity: op }}>{children}</AbsoluteFill>;
};

const Line: React.FC<{ k: string; v: string; good?: boolean; bad?: boolean }> = ({ k, v, good, bad }) => (
  <div style={{ display: 'flex', justifyContent: 'space-between', gap: 24, fontFamily: FONT_MONO, fontSize: 32 }}>
    <span style={{ color: COLORS.d400 }}>{k}</span>
    <span style={{ color: bad ? COLORS.danger : good ? COLORS.signalAlt : COLORS.d300, fontWeight: good || bad ? 700 : 400 }}>{v}</span>
  </div>
);
const Panel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div style={{ background: COLORS.d900, borderRadius: 12, padding: '24px 26px', display: 'flex', flexDirection: 'column', gap: 16 }}>{children}</div>
);

const Short126: React.FC = () => {
  const frame = useCurrentFrame();
  const CTA = secToFrame(30.3);
  const ctaOp = interpolate(frame, [CTA, CTA + 12], [0, 1], { ...CLAMP, easing: EASINGS.easeOut });
  const lines = [{ text: 'STORAGE FEE' }, { text: 'DOUBLES JAN 1', accent: true }];
  return (
    <AbsoluteFill>
      <ShortBg />
      <FadeOut at={secToFrame(3.1)}>
        <CoverImage src="projects/short-126/cover.png" out={secToFrame(3.1) - 10} />
        <HookTitle hold onDark kicker="GEMINI API" lines={lines} />
      </FadeOut>
      <FadeOut at={secToFrame(5.8)}>
        <ToolCard name="Context caching storage" tagline="Gemini 3.8 Flash." chip="STORAGE" at={secToFrame(3.1) - 2} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="billed per" v="1M tokens / hour" />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={secToFrame(12.8)}>
        <ToolCard name="Today" tagline="Through Dec 31." chip="$0.50" at={secToFrame(5.8) - 2}>
          <Panel>
            <Line k="storage /1M /hr" v="$0.50" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={secToFrame(15.5)}>
        <ToolCard name="From Jan 1, 2027" tagline="Storage doubles." chip="$1.00" at={secToFrame(12.8) - 2} chipColor={COLORS.danger}>
          <Panel>
            <Line k="storage /1M /hr" v="$1.00" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={secToFrame(21.2)}>
        <ToolCard name="Cache reads too" tagline="Per 1M tokens." chip="2X" at={secToFrame(15.5) - 2} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="now" v="$0.075" good />
            <Line k="Jan 1" v="$0.15" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={secToFrame(23.8)}>
        <ToolCard name="Keep lifetimes short" tagline="Storage adds up." chip="TTL" at={secToFrame(21.2) - 2} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="tokens stored" v="1M" />
            <Line k="for" v="24 hours" />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={secToFrame(27.8)}>
        <ToolCard name="Stored a day today" tagline="Storage only." chip="$12" at={secToFrame(23.8) - 2}>
          <Panel>
            <Line k="0.50 x 24 h" v="$12.00" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={CTA}>
        <ToolCard name="Stored a day in Jan" tagline="Storage only." chip="$24" at={secToFrame(27.8) - 2} chipColor={COLORS.danger}>
          <Panel>
            <Line k="1.00 x 24 h" v="$24.00" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <AbsoluteFill style={{ opacity: ctaOp }}>
        <CoverImage src="projects/short-126/cover.png" at={CTA} />
        <HookTitle hold onDark at={CTA} kicker="GEMINI API" lines={lines} />
        <div style={{ position: 'absolute', left: SAFE.side, right: SAFE.side, top: SAFE.top + 520, textAlign: 'center', fontFamily: FONT_BODY, fontWeight: 600, fontSize: 44, color: 'rgba(255,255,255,0.82)' }}>
          Google doubles the storage fee.
        </div>
      </AbsoluteFill>
      <CaptionTrack words={WORDS} />
      <Watermark at={12} />
      <ProgressBar />
    </AbsoluteFill>
  );
};
export default Short126;
